inline void to_config(const Settings &settings, p6_config *config)
{
    config->flags = 0u;
    config->machine = settings.machine;
    config->video_standard = settings.video_standard;
    config->chip_kib = settings.chip_size;
    config->slow_kib = settings.slow_size;
    config->fast_kib = settings.fast_size;
    config->fpu_model = settings.fpu_model;
    config->z3_memory = settings.z3_memory;
    config->collision_level = settings.collision_level;
    config->cpu_model = settings.cpu_model;
    config->cpu_compatibility = settings.cpu_compatibility;
    config->cpu_multiplier = settings.cpu_multiplier;
    config->hdf_controller = settings.hdf_controller;
    config->audio_rate_hz = settings.audio_rate_hz;
    config->sound_separation = settings.sound_separation;
    config->sound_interpolation = settings.sound_interpolation;
    config->sound_filter = settings.sound_filter;
    config->sound_filter_type = settings.sound_filter_type;
    config->random_seed = settings.random_seed;
    config->rtc_epoch_seconds = settings.rtc_epoch_seconds;
    config->flags |= settings.floppy_writes;
    config->flags |= settings.cartridge;
    config->floppy_speed = settings.floppy_speed;
    config->floppy_drives = settings.floppy_drive_count;
    config->video_resolution = settings.video_resolution;
    config->video_line_mode = settings.video_line_mode;
}

